INSERT INTO faq (category, question, answer) VALUES
('Ерөнхий', 'Эрчим хүчний аудит гэж юу вэ?', 'Барилга, үйлдвэрийн эрчим хүчний хэрэглээг хэмжиж, алдагдал хаана гарч байгааг тодорхойлж, хэмнэлтийн арга хэмжээ, хөрөнгө оруулалт, эргэн төлөгдөх хугацааг тооцсон тайлан гаргах үйлчилгээ.'),
('Ерөнхий', 'Аудит хийлгэснээр хэр хэмнэлт гарах вэ?', 'Манай туршлагаар эхний жилд эрчим хүчний зардал 10–30% буурч, хүлэмжийн хийн ялгарал 10–30% буурдаг. Хөрөнгө оруулалтын дундаж эргэн төлөгдөх хугацаа 18–36 сар.'),
('Ерөнхий', 'Анхан шатны зөвлөгөө үнэгүй юу?', 'Тийм. 30 минутын анхан шатны зөвлөгөө үнэгүй. Онлайн эсвэл биечлэн уулзаж болно.'),
('Хууль, журам', 'Аудит заавал хийлгэх ёстой юу?', 'Эрчим хүч хэмнэлтийн тухай хуулиар томоохон хэрэглэгч (тодорхой хэмжээнээс дээш эрчим хүч хэрэглэдэг) байгууллагууд тогтмол хугацаанд эрчим хүчний аудит хийлгэх, эрчим хүчний менежертэй байх үүрэгтэй. Дэлгэрэнгүйг манай зөвлөхөөс лавлана уу.'),
('Гэрчилгээ', 'Ногоон зээлд ямар гэрчилгээ хэрэгтэй вэ?', 'Банкууд ногоон зээл, ногоон ипотекийн хувьд барилгын эрчим хүчний гүйцэтгэлийн гэрчилгээ шаарддаг. Бид банкны шаардлагад нийцсэн гэрчилгээ 1–2 долоо хоногт гаргана.'),
('ISO 50001', 'ISO 50001 гэж юу вэ?', 'Эрчим хүчний менежментийн тогтолцооны олон улсын стандарт. Эрчим хүчний хэрэглээг тогтмол хэмжих, зорилт тавих, тасралтгүй сайжруулах процессыг байгууллагад нэвтрүүлнэ.'),
('Процесс', 'Аудит хэрхэн явагддаг вэ?', '1) Суурь нөхцөл байдал, статистик мэдээлэл цуглуулах 2) Газар дээр хэмжилт (тепловизор, цахилгааны анализатор) 3) Дүн шинжилгээ 4) Хэмнэлтийн арга хэмжээ, хөрөнгө оруулалтын тооцоо 5) Тайлан, ажлын төлөвлөгөө хүлээлгэн өгөх.'),
('Процесс', 'Аудитад ямар мэдээлэл бэлдэх вэ?', 'Сүүлийн 1–3 жилийн цахилгаан, дулаан, усны төлбөрийн баримт, барилгын талбай, зураг төсөл, үндсэн тоног төхөөрөмжийн жагсаалт.'),
('Холбоо барих', 'Хаяг, утас?', 'Утас: +976 8811 3855, и-мэйл: energybalance.mgl@gmail.com, хаяг: ХУД 8-р хороо, Нүхт 247.');
